const TAU=Math.PI*2;
export function drawAccessoryProjectile(c,p,time){c.save();c.translate(p.x,p.y);c.rotate(Math.atan2(p.vy,p.vx));c.strokeStyle=p.kind==='ice'?'#8ed7f6aa':'#ccd6d188';c.lineWidth=p.kind==='ice'?5:2;c.beginPath();c.moveTo(-30,0);c.lineTo(0,0);c.stroke();c.fillStyle=p.kind==='ice'?'#c7f3ff':'#e0e5dd';c.strokeStyle=p.kind==='ice'?'#78c9eb':'#8b9c98';c.lineWidth=1.3;c.beginPath();if(p.kind==='ice'){c.moveTo(15,0);c.lineTo(-4,-8);c.lineTo(-12,0);c.lineTo(-4,8)}else{c.moveTo(9,0);c.lineTo(-7,-3);c.lineTo(-3,4)}c.closePath();c.fill();c.stroke();if(p.kind==='ice'){c.strokeStyle='#ffffff';c.lineWidth=1;c.beginPath();c.moveTo(-7,0);c.lineTo(11,0);c.stroke()}c.restore()}
export function drawAccessoryEffect(c,z,r,time){c.save();c.globalAlpha=Math.min(1,z.life/(z.duration||.5));if(z.kind==='magnetic'){c.translate(r.x,r.y);for(let i=0;i<3;i++){c.strokeStyle=i%2?'#dabaffaa':'#b1a7f666';c.lineWidth=2;c.beginPath();c.arc(0,0,z.radius-i*8,time*2+i,time*2+i+TAU*.65);c.stroke()}for(let i=0;i<8;i++){const a=time*2+i*TAU/8;c.fillStyle='#f2dfff';c.fillRect(Math.cos(a)*z.radius-2,Math.sin(a)*z.radius-2,4,4)}}else if(z.kind==='pressure'){const u=1-z.life/z.duration;for(let i=0;i<14;i++){const a=i*TAU/14,radius=z.radius*(.2+u*.8);c.strokeStyle='#d2edf1';c.lineWidth=3*(1-u)+1;c.beginPath();c.arc(z.x,z.y,radius,a,a+.22);c.stroke();c.beginPath();c.moveTo(z.x+Math.cos(a)*radius*.65,z.y+Math.sin(a)*radius*.65);c.lineTo(z.x+Math.cos(a)*(radius+13),z.y+Math.sin(a)*(radius+13));c.stroke()}}else if(z.kind==='coldCone'){c.translate(z.x,z.y);c.rotate(z.angle);c.beginPath();c.moveTo(0,0);c.arc(0,0,z.length,-z.halfAngle,z.halfAngle);c.closePath();c.clip();for(let i=0;i<24;i++){const u=((i*.618+time*1.3)%1),a=Math.sin(i*2.1+time)*z.halfAngle*.9,x=Math.cos(a)*z.length*u,y=Math.sin(a)*z.length*u;c.fillStyle=i%3?'#92d9ec55':'#d4f5ff88';c.beginPath();c.ellipse(x,y,10+u*18,6+u*13,0,0,TAU);c.fill();if(i%4===0){c.strokeStyle='#e0fbff';c.lineWidth=1;c.beginPath();c.moveTo(x-4,y);c.lineTo(x+4,y);c.moveTo(x,y-4);c.lineTo(x,y+4);c.stroke()}}}c.restore()}
export function drawEquipmentDrop(c,d,time){const muzzle=d.rewardKind==='muzzle',color=muzzle?'#91e5ff':'#e0b7ff',y=d.y+Math.sin(time*3+d.x)*3;c.save();c.translate(d.x,y);const glow=c.createRadialGradient(0,0,4,0,0,40);glow.addColorStop(0,muzzle?'#79dfff55':'#d19fff55');glow.addColorStop(1,'#9ecfff00');c.fillStyle=glow;c.beginPath();c.arc(0,0,40,0,TAU);c.fill();c.fillStyle='#24313a';c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.moveTo(-17,-13);c.lineTo(17,-13);c.lineTo(22,0);c.lineTo(17,14);c.lineTo(-17,14);c.lineTo(-22,0);c.closePath();c.fill();c.stroke();c.fillStyle=color;c.font='bold 22px sans-serif';c.textAlign='center';c.fillText(muzzle?'⑂':'⚙',0,7);c.font='bold 11px sans-serif';c.strokeStyle='#17251e';c.lineWidth=3;const label=muzzle?'枪口战利品':'配件战利品';c.strokeText(label,0,-24);c.fillText(label,0,-24);c.font='10px sans-serif';c.fillText('靠近拾取',0,32);c.restore()}
